      fullDesc: "انسان‌ها جوان‌ترین نژاد بزرگ‌اند — دیر آفریده شدند، پس از آنکه آلدِرین و سیلوار و درائِکون تخت‌هایشان را تصاحب کرده بودند. اما آنچه در سال ندارند، در شمار و اراده‌ی بی‌قرار جبران می‌کنند. هزار سال پس از شکاف، تاریخ بشریت داستانِ برخاستن و افتادن است، امپراتوران و غاصبان، پادشاهی‌هایی که بر استخوان بنا شدند و با خیانت به خاک سپرده شدند. بزرگ‌ترینشان همه، امپراتور والریوس شکست‌ناپذیر بود، که قبایل متخاصم انسانی را یکی کرد و امپراتوری والریان را ساخت — بزرگ‌ترین امپراتوری تاریخ ثبت‌شده. پایتختش هنوز برپاست، درست بالای هاویه، و خونش هنوز فرمان می‌راند — هرچند امپراتوری از دیرباز به ده‌ها دولت جانشین تجزیه شده. انسان‌ها ذاتاً نه بدند، نه خوب. آن‌ها فقط رانده‌اند — با گرسنگی، با ترس، با عشق، با نفرت — و همین رانش، خطرناک‌ترین نژاد جهان را ساخته است.",
      secret: "امپراتوری والریان نمرده — فقط خفته است. امپراتور کنونی، نواده‌ی دور والریوس، چهل سال است در نهان اتحاد می‌سازد و سنگ مانا انبار می‌کند. باور دارد مقدر است بشریت را یکی کند. احتمالاً حق دارد. و حاضره هر کاری — هر کاری — بکنه تا این اتفاق بیفته. حتی اگه «هر کاری» یعنی باز کردن مهر خدا.",
      culture: "فرهنگ انسانی یک فرهنگ نیست — هزاران فرهنگ است. هر پادشاهی آداب خودش را دارد، خدایان خودش، کینه‌های خودش. آنچه یکشان می‌کند، باور مشترک به توانایی بشر است — و آمادگی مشترک برای خیانت به آن در ازای یک تاج. آشپزی انسانی متنوع و غنی است. موسیقی‌شان بلند و پرشور است. هنرشان وسواس میراث دارد — وسواس به یاد ماندن.",
