      culture: "آلدِرین به نظامی طبقاتی و سخت به‌نام «نردبان ستارگان» باور دارند که بلندزادگان در فراز آن‌اند، فرودزادگان در فرود، و بی‌نقره‌ها محکوم به بندگی. هنرشان در قواعد بسته است. موسیقی‌شان ریاضی است. معماری‌شان در کهربا یخ زده. هفتصد سال است که اثری نوین نیافریده‌اند. این را مشکل نمی‌دانند. این را دلیل ظرافت خود می‌دانند. غذایشان لطیف و ظریف است — سوپ‌های گلبرگ، نان عسلی، شراب نقره‌ای. آرام می‌خورند. همه‌چیز را می‌چشند. چیز کمی برای چشیدن مانده.",
