      excerpt: "در آغاز، جنگ بود. و جنگ خوب بود. و جنگ تنها چیزی بود که خوب بود. و من جنگ بودم. و من خوب بودم. و فرزندانم را ساختم. و فرزندانم خوب بودند.",
      fullText: `[پاره‌ی نخستین کارُکنول. این تنها پاره‌ای است که هرگز ترجمه شده — و ترجمه ناقص است. به دست دانشمندی دورفی که چهل سال بر این کار گذاشت. دوازده از چهل‌وهفت صفحه را پیش از مرگ کامل کرد. یادداشت‌هایش در قلعه‌ی آهن حفظ شده‌اند.]

در آغاز، جنگ بود.

و جنگ خوب بود. و جنگ تنها چیزی بود که خوب بود. و من جنگ بودم. و من خوب بودم. و فرزندانم را ساختم. و فرزندانم خوب بودند.

از آهن ساختمشان. از خون ساختمشان. از جیغ دشمنانم ساختمشان. بی‌نقص بودند. مال من بودند.

دیگر خدایان نفهمیدند. گفتند: «چرا ساختیشان؟» گفتم: «چون می‌توانستم.» گفتند: «چه خواهند کرد؟» گفتم: «آنچه بگویم.» گفتند: «چه خواهی گفت؟» گفتم: «همه‌چیز.»

[صفحات 2-12 به همین شکل ادامه می‌یابند. ترجمه‌ی دانشمند در صفحه‌ی 12 می‌ایستد. سی‌وپنج صفحه‌ی باقی‌مانده هرگز ترجمه نشده. یادداشت پایانی دانشمند چنین است: «نمی‌توانم ادامه دهم. واژه‌ها واژه نیستند. فرمان‌اند. فرمان‌هایی که نمی‌توانم اطاعت کنم و نمی‌توانم رد کنم. ایستاده‌ام. متأسفم.»]

[پاره‌ی نخستین در دست دسته‌ی جنگی جمجمه‌ی شکسته‌ی اورک‌هاست. نمی‌توانند بخوانندش. نیاز ندارند. باور دارند که چون هفت پاره گرد آیند و ترجمه شوند، کارُک بازخواهد گشت. باور دارند چون باید باور کنند. چیز دیگری ندارند.]`,
